with flagged as (select *, case when txn_time - lag(txn_time) over (partition by txn_type order by txn_time, id) > interval 60 days then 1 else 0 end as is_new_burst from transactions), islands as (select *, sum(is_new_burst) over (partition by txn_type order by txn_time, id rows between unbounded preceding and current row) as island_id from flagged) select s.id, s.account_id, s.txn_type, s.amount, s.merchant, s.is_flagged, s.is_new_burst, case when txn_type rlike '^(CREDIT|REFUND)$' then 'GROUP_A' else 'OTHER_ZONE' end as txn_type_zone, (select max(x.amount) from transactions x where x.account_id = s.account_id) as max_transaction_amount from islands s
